#ifndef  _POWERPC_H
#define  _POWERPC_H

#include "powerpc_parms.H"
#include "systemc.h"
#include "ac_module.H"
#include "ac_utils.H"
#include "powerpc_arch.H"
#include "powerpc_isa.H"
#include "powerpc_syscall.H"


class powerpc: public ac_module, public powerpc_arch {
private:
  typedef struct {
    uint8_t op;
    uint8_t rt;
    uint8_t ra;
    uint8_t rb;
    uint8_t oe;
    uint16_t xo;
  } T_Type_XO;

  typedef struct {
    uint8_t op;
    uint8_t rt;
    uint8_t ra;
    int16_t d;
  } T_Type_D;

  typedef struct {
    uint8_t op;
    uint8_t bo;
    uint8_t bi;
    int16_t bd;
    uint8_t aa;
    uint8_t lk;
  } T_Type_B;

  typedef struct {
    uint8_t op;
    int32_t li;
    uint8_t aa;
    uint8_t lk;
  } T_Type_I;

  typedef struct {
    uint8_t op;
    uint32_t imm;
  } T_Type_HLT;

  typedef struct {
    bool valid;
    void* end_rot;
    unsigned id;
    union {
      T_Type_XO F_Type_XO;
      T_Type_D F_Type_D;
      T_Type_B F_Type_B;
      T_Type_I F_Type_I;
      T_Type_HLT F_Type_HLT;
    };
  } DecCacheItem ;

public:

  bool has_delayed_load;
  char* delayed_load_program;
  powerpc_parms::powerpc_isa ISA;
  //!Address of Interpretation Routines.
  void** IntRoutine;

  DecCacheItem* DEC_CACHE;
  DecCacheItem* instr_dec;
  bool start_up;

  //!Dispatch Method.
  inline __attribute__((always_inline)) void* dispatch();

  //!Behavior execution method.
  void behavior();

  SC_HAS_PROCESS( powerpc );

  sc_event wake;

  //!Constructor.
  powerpc( sc_module_name name_ ): ac_module(name_), powerpc_arch(), ISA(*this) {
    SC_THREAD( behavior );
    sensitive << wake;
    has_delayed_load = false; 
    start_up=1;
    ac_id.write(globalId++);
  }

  void init_dec_cache() {
    DEC_CACHE = (DecCacheItem*) calloc(sizeof(DecCacheItem), (dec_cache_size / 4));
  }

  unsigned get_ac_pc();

  void set_ac_pc( unsigned int value );

  virtual void PrintStat();

  void init(int ac, char* av[]);

  void init();

  void set_prog_args();

  void load(char* program);

  void delayed_load(char* program);

  void stop(int status = 0);

  virtual ~powerpc() {};

};
#endif  //_POWERPC_H

